using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Synkoz {internal static class FolderTagsR18 {
 internal static Dictionary<string,string> Read(string folder){var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);string path=Path.Combine(folder,"tags.txt");if(!File.Exists(path))return result;string section=null;foreach(string raw in File.ReadAllLines(path)){string line=raw.Trim();if(line.StartsWith("#")||line.Length==0)continue;if(line.StartsWith("[")&&line.EndsWith("]")){section=line.Substring(1,line.Length-2);if(!result.ContainsKey(section))result[section]="";}else if(section!=null)result[section]+=" "+line;}return result;}
 internal static string Tags(string file){var sections=Read(Path.GetDirectoryName(file));string common,specific;sections.TryGetValue("communs",out common);if(!sections.TryGetValue(Path.GetFileName(file),out specific)){string old=file+".tags.txt";specific=File.Exists(old)?File.ReadAllText(old):"";}return (common??"")+" "+(specific??"");}
 internal static void Write(string file,string common,string specific){string path=Path.Combine(Path.GetDirectoryName(file),"tags.txt");var lines=File.Exists(path)?File.ReadAllLines(path).ToList():new List<string>();foreach(var update in new[]{new KeyValuePair<string,string>("communs",common),new KeyValuePair<string,string>(Path.GetFileName(file),specific)}){int start=lines.FindIndex(l=>l.Trim().Equals("["+update.Key+"]",StringComparison.OrdinalIgnoreCase));if(start<0){lines.Add("");lines.Add("["+update.Key+"]");lines.Add(update.Value.Replace('\r',' ').Replace('\n',' '));continue;}int end=start+1;while(end<lines.Count&&!lines[end].TrimStart().StartsWith("["))end++;for(int i=end-1;i>start;i--)if(!lines[i].TrimStart().StartsWith("#"))lines.RemoveAt(i);lines.Insert(start+1,update.Value.Replace('\r',' ').Replace('\n',' '));}File.WriteAllLines(path,lines);}
}}
